mkitem!{mkstruct!{# [doc = " A slot in a channel."] struct Slot < T > { # [doc = " The current stamp."] stamp : Atomic < usize > , # [doc = " The message in this slot. Either read out in `read` or dropped through"] # [doc = " `discard_all_messages`."] msg : UnsafeCell < MaybeUninit < T > > , }}}
mkitem!{mkstruct!{# [doc = " The token type for the array flavor."] # [derive (Debug)] pub (crate) struct ArrayToken { # [doc = " Slot to read from or write to."] slot : * const u8 , # [doc = " Stamp to store into the slot after reading or writing."] stamp : usize , }}}
mkitem!{mkimpl!{impl Default for ArrayToken { # [inline] fn default () -> Self { ArrayToken { slot : ptr :: null () , stamp : 0 } } }}}
mkitem!{mkstruct!{# [doc = " Bounded channel based on a preallocated array."] pub (crate) struct Channel < T > { # [doc = " The head of the channel."] # [doc = ""] # [doc = " This value is a \"stamp\" consisting of an index into the buffer, a mark bit, and a lap, but"] # [doc = " packed into a single `usize`. The lower bits represent the index, while the upper bits"] # [doc = " represent the lap. The mark bit in the head is always zero."] # [doc = ""] # [doc = " Messages are popped from the head of the channel."] head : CachePadded < Atomic < usize > > , # [doc = " The tail of the channel."] # [doc = ""] # [doc = " This value is a \"stamp\" consisting of an index into the buffer, a mark bit, and a lap, but"] # [doc = " packed into a single `usize`. The lower bits represent the index, while the upper bits"] # [doc = " represent the lap. The mark bit indicates that the channel is disconnected."] # [doc = ""] # [doc = " Messages are pushed into the tail of the channel."] tail : CachePadded < Atomic < usize > > , # [doc = " The buffer holding slots."] buffer : Box < [Slot < T >] > , # [doc = " The channel capacity."] cap : usize , # [doc = " A stamp with the value of `{ lap: 1, mark: 0, index: 0 }`."] one_lap : usize , # [doc = " If this bit is set in the tail, that means the channel is disconnected."] mark_bit : usize , # [doc = " Senders waiting while the channel is full."] senders : SyncWaker , # [doc = " Receivers waiting while the channel is empty and not disconnected."] receivers : SyncWaker , }}}
mkitem!{mkimpl!{impl < T > Channel < T > { # [doc = " Creates a bounded channel of capacity `cap`."] pub (crate) fn with_capacity (cap : usize) -> Self { assert ! (cap > 0 , "capacity must be positive") ; let mark_bit = (cap + 1) . next_power_of_two () ; let one_lap = mark_bit * 2 ; let head = 0 ; let tail = 0 ; let buffer : Box < [Slot < T >] > = (0 .. cap) . map (| i | { Slot { stamp : AtomicUsize :: new (i) , msg : UnsafeCell :: new (MaybeUninit :: uninit ()) } }) . collect () ; Channel { buffer , cap , one_lap , mark_bit , head : CachePadded :: new (AtomicUsize :: new (head)) , tail : CachePadded :: new (AtomicUsize :: new (tail)) , senders : SyncWaker :: new () , receivers : SyncWaker :: new () , } } # [doc = " Attempts to reserve a slot for sending a message."] fn start_send (& self , token : & mut Token) -> bool { let backoff = Backoff :: new () ; let mut tail = self . tail . load (Ordering :: Relaxed) ; loop { if tail & self . mark_bit != 0 { token . array . slot = ptr :: null () ; token . array . stamp = 0 ; return true ; } let index = tail & (self . mark_bit - 1) ; let lap = tail & ! (self . one_lap - 1) ; debug_assert ! (index < self . buffer . len ()) ; let slot = unsafe { self . buffer . get_unchecked (index) } ; let stamp = slot . stamp . load (Ordering :: Acquire) ; if tail == stamp { let new_tail = if index + 1 < self . cap { tail + 1 } else { lap . wrapping_add (self . one_lap) } ; match self . tail . compare_exchange_weak (tail , new_tail , Ordering :: SeqCst , Ordering :: Relaxed ,) { Ok (_) => { token . array . slot = slot as * const Slot < T > as * const u8 ; token . array . stamp = tail + 1 ; return true ; } Err (_) => { backoff . spin_light () ; tail = self . tail . load (Ordering :: Relaxed) ; } } } else if stamp . wrapping_add (self . one_lap) == tail + 1 { atomic :: fence (Ordering :: SeqCst) ; let head = self . head . load (Ordering :: Relaxed) ; if head . wrapping_add (self . one_lap) == tail { return false ; } backoff . spin_light () ; tail = self . tail . load (Ordering :: Relaxed) ; } else { backoff . spin_heavy () ; tail = self . tail . load (Ordering :: Relaxed) ; } } } # [doc = " Writes a message into the channel."] pub (crate) unsafe fn write (& self , token : & mut Token , msg : T) -> Result < () , T > { if token . array . slot . is_null () { return Err (msg) ; } unsafe { let slot : & Slot < T > = & * (token . array . slot as * const Slot < T >) ; slot . msg . get () . write (MaybeUninit :: new (msg)) ; slot . stamp . store (token . array . stamp , Ordering :: Release) ; } self . receivers . notify () ; Ok (()) } # [doc = " Attempts to reserve a slot for receiving a message."] fn start_recv (& self , token : & mut Token) -> bool { let backoff = Backoff :: new () ; let mut head = self . head . load (Ordering :: Relaxed) ; loop { let index = head & (self . mark_bit - 1) ; let lap = head & ! (self . one_lap - 1) ; debug_assert ! (index < self . buffer . len ()) ; let slot = unsafe { self . buffer . get_unchecked (index) } ; let stamp = slot . stamp . load (Ordering :: Acquire) ; if head + 1 == stamp { let new = if index + 1 < self . cap { head + 1 } else { lap . wrapping_add (self . one_lap) } ; match self . head . compare_exchange_weak (head , new , Ordering :: SeqCst , Ordering :: Relaxed ,) { Ok (_) => { token . array . slot = slot as * const Slot < T > as * const u8 ; token . array . stamp = head . wrapping_add (self . one_lap) ; return true ; } Err (_) => { backoff . spin_light () ; head = self . head . load (Ordering :: Relaxed) ; } } } else if stamp == head { atomic :: fence (Ordering :: SeqCst) ; let tail = self . tail . load (Ordering :: Relaxed) ; if (tail & ! self . mark_bit) == head { if tail & self . mark_bit != 0 { token . array . slot = ptr :: null () ; token . array . stamp = 0 ; return true ; } else { return false ; } } backoff . spin_light () ; head = self . head . load (Ordering :: Relaxed) ; } else { backoff . spin_heavy () ; head = self . head . load (Ordering :: Relaxed) ; } } } # [doc = " Reads a message from the channel."] pub (crate) unsafe fn read (& self , token : & mut Token) -> Result < T , () > { if token . array . slot . is_null () { return Err (()) ; } let msg = unsafe { let slot : & Slot < T > = & * (token . array . slot as * const Slot < T >) ; let msg = slot . msg . get () . read () . assume_init () ; slot . stamp . store (token . array . stamp , Ordering :: Release) ; msg } ; self . senders . notify () ; Ok (msg) } # [doc = " Attempts to send a message into the channel."] pub (crate) fn try_send (& self , msg : T) -> Result < () , TrySendError < T > > { let token = & mut Token :: default () ; if self . start_send (token) { unsafe { self . write (token , msg) . map_err (TrySendError :: Disconnected) } } else { Err (TrySendError :: Full (msg)) } } # [doc = " Sends a message into the channel."] pub (crate) fn send (& self , msg : T , deadline : Option < Instant > ,) -> Result < () , SendTimeoutError < T > > { let token = & mut Token :: default () ; loop { if self . start_send (token) { let res = unsafe { self . write (token , msg) } ; return res . map_err (SendTimeoutError :: Disconnected) ; } if let Some (d) = deadline { if Instant :: now () >= d { return Err (SendTimeoutError :: Timeout (msg)) ; } } Context :: with (| cx | { let oper = Operation :: hook (token) ; self . senders . register (oper , cx) ; if ! self . is_full () || self . is_disconnected () { let _ = cx . try_select (Selected :: Aborted) ; } let sel = unsafe { cx . wait_until (deadline) } ; match sel { Selected :: Waiting => unreachable ! () , Selected :: Aborted | Selected :: Disconnected => { self . senders . unregister (oper) . unwrap () ; } Selected :: Operation (_) => { } } }) ; } } # [doc = " Attempts to receive a message without blocking."] pub (crate) fn try_recv (& self) -> Result < T , TryRecvError > { let token = & mut Token :: default () ; if self . start_recv (token) { unsafe { self . read (token) . map_err (| _ | TryRecvError :: Disconnected) } } else { Err (TryRecvError :: Empty) } } # [doc = " Receives a message from the channel."] pub (crate) fn recv (& self , deadline : Option < Instant >) -> Result < T , RecvTimeoutError > { let token = & mut Token :: default () ; loop { if self . start_recv (token) { let res = unsafe { self . read (token) } ; return res . map_err (| _ | RecvTimeoutError :: Disconnected) ; } if let Some (d) = deadline { if Instant :: now () >= d { return Err (RecvTimeoutError :: Timeout) ; } } Context :: with (| cx | { let oper = Operation :: hook (token) ; self . receivers . register (oper , cx) ; if ! self . is_empty () || self . is_disconnected () { let _ = cx . try_select (Selected :: Aborted) ; } let sel = unsafe { cx . wait_until (deadline) } ; match sel { Selected :: Waiting => unreachable ! () , Selected :: Aborted | Selected :: Disconnected => { self . receivers . unregister (oper) . unwrap () ; } Selected :: Operation (_) => { } } }) ; } } # [doc = " Returns the current number of messages inside the channel."] pub (crate) fn len (& self) -> usize { loop { let tail = self . tail . load (Ordering :: SeqCst) ; let head = self . head . load (Ordering :: SeqCst) ; if self . tail . load (Ordering :: SeqCst) == tail { let hix = head & (self . mark_bit - 1) ; let tix = tail & (self . mark_bit - 1) ; return if hix < tix { tix - hix } else if hix > tix { self . cap - hix + tix } else if (tail & ! self . mark_bit) == head { 0 } else { self . cap } ; } } } # [doc = " Returns the capacity of the channel."] # [allow (clippy :: unnecessary_wraps)] pub (crate) fn capacity (& self) -> Option < usize > { Some (self . cap) } # [doc = " Disconnects senders and wakes up all blocked receivers."] # [doc = ""] # [doc = " Returns `true` if this call disconnected the channel."] pub (crate) fn disconnect_senders (& self) -> bool { let tail = self . tail . fetch_or (self . mark_bit , Ordering :: SeqCst) ; if tail & self . mark_bit == 0 { self . receivers . disconnect () ; true } else { false } } # [doc = " Disconnects receivers and wakes up all blocked senders."] # [doc = ""] # [doc = " Returns `true` if this call disconnected the channel."] # [doc = ""] # [doc = " # Safety"] # [doc = " May only be called once upon dropping the last receiver. The"] # [doc = " destruction of all other receivers must have been observed with acquire"] # [doc = " ordering or stronger."] pub (crate) unsafe fn disconnect_receivers (& self) -> bool { let tail = self . tail . fetch_or (self . mark_bit , Ordering :: SeqCst) ; let disconnected = if tail & self . mark_bit == 0 { self . senders . disconnect () ; true } else { false } ; unsafe { self . discard_all_messages (tail) } ; disconnected } # [doc = " Discards all messages."] # [doc = ""] # [doc = " `tail` should be the current (and therefore last) value of `tail`."] # [doc = ""] # [doc = " # Panicking"] # [doc = " If a destructor panics, the remaining messages are leaked, matching the"] # [doc = " behavior of the unbounded channel."] # [doc = ""] # [doc = " # Safety"] # [doc = " This method must only be called when dropping the last receiver. The"] # [doc = " destruction of all other receivers must have been observed with acquire"] # [doc = " ordering or stronger."] unsafe fn discard_all_messages (& self , tail : usize) { debug_assert ! (self . is_disconnected ()) ; let mut head = self . head . load (Ordering :: Relaxed) ; let tail = tail & ! self . mark_bit ; let backoff = Backoff :: new () ; loop { let index = head & (self . mark_bit - 1) ; let lap = head & ! (self . one_lap - 1) ; debug_assert ! (index < self . buffer . len ()) ; let slot = unsafe { self . buffer . get_unchecked (index) } ; let stamp = slot . stamp . load (Ordering :: Acquire) ; if head + 1 == stamp { head = if index + 1 < self . cap { head + 1 } else { lap . wrapping_add (self . one_lap) } ; unsafe { (* slot . msg . get ()) . assume_init_drop () ; } } else if tail == head { return ; } else { backoff . spin_heavy () ; } } } # [doc = " Returns `true` if the channel is disconnected."] pub (crate) fn is_disconnected (& self) -> bool { self . tail . load (Ordering :: SeqCst) & self . mark_bit != 0 } # [doc = " Returns `true` if the channel is empty."] pub (crate) fn is_empty (& self) -> bool { let head = self . head . load (Ordering :: SeqCst) ; let tail = self . tail . load (Ordering :: SeqCst) ; (tail & ! self . mark_bit) == head } # [doc = " Returns `true` if the channel is full."] pub (crate) fn is_full (& self) -> bool { let tail = self . tail . load (Ordering :: SeqCst) ; let head = self . head . load (Ordering :: SeqCst) ; head . wrapping_add (self . one_lap) == tail & ! self . mark_bit } }}}